        "a hairy man, with a leather belt",
        "comm",
        "Note",
        "Note",
        """<strong>Elijah’s costume.</strong> The hairy garment and leather belt become the iconic prophetic uniform. John the Baptist consciously assumes it (Mt 3:4 — same description, same diet of locusts and wild honey), and Mal 4:5–6’s promise of Elijah’s return is read by Jesus (Mt 11:14, 17:11–13) as fulfilled in John. Zech 13:4 mentions the hairy mantle as the prophetic dress that false prophets imitated. Elijah’s sartorial signature thus becomes a recurring sign in the canonical text — the costume of the prophetic office and of eschatological expectation.""",
        "User original",
