    (
        3,
        27,
        "",
        "offered him for a burnt offering",
        "comm",
        "Note",
        "Note",
        """<strong>Mesha’s child sacrifice.</strong> The Mesha Stele (Moabite, c. 840 BCE) gives the Moabite king’s own account of his wars with Israel, and is the longest extant text in the Moabite language. The biblical detail of Mesha sacrificing his son on the wall — and ’great wrath’ coming on Israel afterward — is theologically opaque: whose wrath? Some commentators read it as Chemosh effectively responding to the sacrifice; others as Yahweh withdrawing because of Israel’s complicity in driving Mesha to such an act.""",
        "User original",
    ),
