    (
        4,
        8,
        "",
        "a great woman",
        "comm",
        "Note",
        "Note",
        """<strong>The Shunammite.</strong> The Hebrew <em>ishah gedolah</em> can mean "wealthy" or "of high social standing." She is unnamed throughout, identified only by her town (Shunem in Issachar). Her arc is one of the OT’s richest portraits of a woman of independent means: she initiates hospitality, builds a guest room, refuses Elisha’s offers of patronage ("I dwell among my own people"). Her son’s death and resuscitation (4:18–37) anticipate similar miracles by Jesus (Mk 5:35–43, Lk 7:11–17) and Peter (Acts 9:36–42). She returns in 8:1–6 — claiming back her land — making her a recurring character across the cycle.""",
        "User original",
    ),
