    (
        5,
        18,
        "",
        "the house of Rimmon",
        "comm-orthodox",
        "Note",
        "Note",
        '<strong>Rimmon and conscience.</strong> Naaman, now a Yahweh-worshiper, asks pardon for an unavoidable cultic compromise: when his master leans on his arm in the temple of Rimmon (a Damascene storm-god) and bows, he must bow with him. Elisha’s reply — "Go in peace" — is one of the OT’s most pastorally sensitive moments. The verse becomes a touchstone in Christian moral-theological discussion of conscience in compromised circumstances; the term "bowing in the house of Rimmon" enters English ethical vocabulary as shorthand for outward conformity that the conscience does not approve.',
        "User original",
    ),
