    (
        6,
        17,
        "",
        "the mountain was full of horses and chariots of fire",
        "comm",
        "Note",
        "Note",
        """<strong>"Those who are with us are more."</strong> Elisha prays for his servant’s eyes to be opened, and the servant sees the heavenly army surrounding the prophet. The verse is one of the OT’s clearest depictions of an unseen heavenly reality coexisting with the visible one — a narrative analogue to what later theology will call the "two cities" or "two kingdoms" overlapping. The mountain of fire-chariots inverts the Aramean siege: what looks like overwhelming earthly force is enveloped by greater heavenly force. The verse is a foundational text for biblical depictions of providence and angelic protection.""",
        "User original",
    ),
