    (
        9,
        22,
        "",
        "the prostitution of your mother Jezebel",
        "comm",
        "Note",
        "Note",
        """<strong>Jehu’s revolt.</strong> Jehu, anointed by an Elisha-sent prophet, executes Jezebel’s entire dynastic line, the Baal priesthood, and Ahaziah of Judah’s relatives. Hosea 1:4 will later condemn the bloodshed of Jezreel — a remarkable internal-canonical critique. Kings frames Jehu as fulfilling Elijah’s prophecy (1 Kgs 21:21–24); Hosea reads the same events as a crime requiring divine response. The two readings are not necessarily contradictory — Jehu fulfilled the prophecy while exceeding the warrant — but the canonical preservation of both registers a complex relationship between divine commission and human violence.""",
        "User original",
    ),
