    (
        9,
        30,
        "",
        "painted her eyes",
        "comm",
        "Note",
        "Note",
        """<strong>Jezebel’s death.</strong> Jezebel paints her eyes and dresses her hair before her death — a final royal performance, not vanity. She greets Jehu by invoking Zimri (v. 31), another regicide who lasted only seven days; the comparison is strategic. Her death by being thrown from the window and trampled, with dogs eating her body, fulfills Elijah’s word from 1 Kgs 21:23.""",
        "User original",
    ),
