        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>JONADAB</strong> =Jehon’adab. (1.) The son of Rechab, and founder of the Rechabites (q.v.), 2 Kings 10:15; Jeremiah 35:6, 10. (2.) The son of Shimeah, David’s brother (2 Samuel 13:3). He was “a very subtil man.”",
