    (
        11,
        1,
        "",
        "Athaliah",
        "comm",
        "Note",
        "Note",
        """<strong>Athaliah.</strong> Daughter of Ahab and Jezebel (or possibly of Omri — sources differ), Athaliah is the only woman to reign in her own right in the Davidic line. Her seven-year usurpation involves the attempted extermination of the Davidic seed; only the infant Joash, hidden by his aunt Jehosheba in the temple, survives. Her overthrow by Jehoiada the priest is one of the OT’s few palace coups led by a religious establishment. The narrative’s preservation of the Davidic line through one hidden infant becomes, for Christian typological reading, a structural prefiguration of Bethlehem (Mt 2). The line came within a single child of extinction.""",
        "User original",
    ),
