    (
        14,
        9,
        "a",
        "",
        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>THISTLE</strong> (1.) Hebrews hoah (2 Kings 14:9; Job 31:40). In Job 41:2 the Hebrew word is rendered “thorn,” but in the Revised Version “hook.” It is also rendered “thorn” in 2 Chronicles 33:11; Proverbs 26:9; Cant. 2:2; “brambles” in Isaiah 34:13. It is supposed to be a variety of the wild plum-tree, but by some it is regarded as the common thistle, of which there are many varieties in Palestine. (2.) Hebrews dardar, meaning “a plant growing luxuriantly” (Genesis 3:18; Hos. 10:8); Gr. tribolos, “a triple point” (Matthew 7:16; Hebrews 6:8, “brier,” R.V. “thistle”). This was probably the star-thistle, called by botanists Centaurea calcitropa, or “caltrops,” a weed common in corn-fields. (See THORNS.)",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
    ),
