        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>PEKAHIAH</strong> the Lord opened his eyes, the son and successor of Menahem on the throne of Israel. He was murdered in the royal palace of Samaria by Pekah, one of the captains of his army (2 Kings 15:23-26), after a reign of two years (B.C. 761-759). He “did that which was evil in the sight of the Lord.”",
