    (
        17,
        6,
        "",
        "carried Israel away into Assyria",
        "comm",
        "Note",
        "Note",
        """<strong>The fall of Samaria.</strong> 722 BCE. The northern kingdom ends after roughly two centuries of independent existence. The Assyrian deportation policy — moving conquered populations to break their ethnic-religious cohesion — sends the ten northern tribes into exile from which they do not return as a corporate people. The "ten lost tribes" become the seedbed of countless legends and identity-claims (from the Bnei Menashe of India to the British Israelism movement). The Assyrian records — the Khorsabad annals of Sargon II — independently confirm the campaign and give the deportation number as 27,290.""",
        "User original",
    ),
    (
        17,
        6,
        "a",
        "",
        "topic-nave",
        "Topic",
        "Topic.",
        "<strong>Topics.</strong> This verse appears under: ASSYRIA, ASSYRIA, BABYLON, CAPTIVITY, COLONIZATION.",
        "Nave's Topical Bible, Orville J. Nave (1896). Public domain.",
    ),
    (
        17,
        6,
        "b",
        "",
        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>GOZAN</strong> a region in Central Asia to which the Israelites were carried away captive (2 Kings 17:6; 1 Chronicles 5:26; 2 Kings 19:12; Isaiah 37:12). It was situated in Mesopotamia, on the river Habor (2 Kings 17:6; 18:11), the Khabur, a tributary of the Euphrates. The “river of Gozan” (1 Chronicles 5:26) is probably the upper part of the river flowing through the province of Gozan, now Kizzel-Ozan.",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
    ),
    (
        17,
        6,
        "c",
        "",
        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>HALAH</strong> a district of Media to which captive Israelites were transported by the Assyrian kings (2 Kings 17:6; 18:11; 1 Chronicles 5:26). It lay along the banks of the upper Khabur, from its source to its junction with the Jerujer. Probably the district called by Ptolemy Chalcitis.",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
    ),
