    (
        17,
        23,
        "",
        "because of the sins of Jeroboam",
        "comm",
        "Note",
        "Note",
        """<strong>The Deuteronomistic verdict.</strong> 2 Kgs 17:7–23 is the historian’s extended theological autopsy of the northern kingdom — the longest such reflection in Kings. The verdict: the fall is the consequence of Jeroboam’s calves and the cumulative apostasy of every northern king who walked in his ways. The passage is the Deuteronomistic theology in its most explicit form: covenant violation produces covenant curse. The southern kingdom, observing this judgment from a distance, will be told (and will largely fail to hear) that the same logic applies to Judah.""",
        "User original",
    ),
