    (
        17,
        24,
        "",
        "people from Babylon, and from Cuthah",
        "comm",
        "Note",
        "Note",
        """<strong>The origin of the Samaritans.</strong> The narrator’s etiology of the post-exilic Samaritan community is told from a Judean POV and would have been rejected by the Samaritans themselves, who traced their lineage back to pre-exilic Israelite tribes (especially Ephraim and Manasseh). The passage’s mixed-religion framing (’they feared Yahweh and served their own gods,’ v. 33) shaped centuries of Jewish-Samaritan polemics, still echoing in the Gospel of John.""",
        "User original",
    ),
    (
        17,
        24,
        "a",
        "",
        "text-witness",
        "Witness",
        "MS.",
        "<strong>Manuscript witness.</strong> ephus, was Manasseh. This Manasseh, in indignation at his expulsion, took refuge among the Samaritans, and set up among them a rival worehip to that at Jerusalem. The Samaritans, whom we know from 2 Kings 17. 24-41 to have been foreigners imported into the country of the Ten Tribes by the king of Assyria, and there, presumably, to have mingled with the scanty remnant of Israelites, had at first incorporated",
        "Frederic G. Kenyon, *Our Bible and the Ancient Manuscripts* (Eyre & Spottiswoode, London, 1895). Public domain.",
    ),
