    (
        17,
        24,
        "c",
        "",
        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>CUTHAH</strong> one of the Babylonian cities or districts from which Shalmaneser transplanted certain colonists to Samaria (2 Kings 17:24). Some have conjectured that the “Cutheans” were identical with the “Cossaeans” who inhabited the hill-country to the north of the river Choaspes. Cuthah is now identified with Tell Ibrahim, 15 miles north-east of Babylon.",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
    ),
    (
        17,
        24,
        "d",
        "",
        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>SEPHARVAIM</strong> taken by Sargon, king of Assyria (2 Kings 17:24; 18:34; 19:13; Isaiah 37:13). It was a double city, and received the common name Sepharvaim, i.e., “the two Sipparas,” or “the two booktowns.” The Sippara on the east bank of the Euphrates is now called Abu-Habba; that on the other bank was Accad, the old capital of Sargon I., where he established a great library. (See SARGON.) The recent discovery of cuneiform inscriptions at Tel el-Amarna in Egypt, consisting of official despatches to Pharaoh Amenophis IV. and his predecessor from their agents in Palestine, proves that in the century before the Exodus an active literary intercourse was carried on between these nations, and that the medium of the correspondence was the Babylonian language and script. (See KIRJATH-SEPHER.)",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
    ),
