        "<strong>Dictionary (Easton's).</strong> <strong>ADRAMMELECH</strong> Adar the king. (1.) An idol; a form of the sun-God worshipped by the inhabitants of Sepharvaim (2 Kings 17:31), and brought by the Sepharvite colonists into Samaria. (2.) A son of Sennacherib, king of Assyria (2 Kings 19:37; Isaiah 37:38).",
