    (
        18,
        4,
        "",
        "broke in pieces the bronze serpent",
        "comm-orthodox",
        "Note",
        "Note",
        "<strong>Hezekiah’s reform.</strong> Hezekiah destroys the high places, sacred pillars, Asherah poles — and Nehushtan, the bronze serpent Moses had made (Num 21:9), now an object of incense-offering. The detail is theologically pointed: even a Mosaic relic, when made an end in itself, must be destroyed. The principle — that authentic religion sometimes requires destroying its own historical objects when they have become idols — runs through the Hebrew prophetic tradition and animates later iconoclastic movements (Byzantine, Protestant). Nehushtan’s removal becomes a paradigm case.",
        "User original",
    ),
