        "<strong>Dictionary (Easton's).</strong> <strong>FULLER’S FIELD</strong> a spot near Jerusalem (2 Kings 18:17; Isaiah 36:2; 7:3), on the side of the highway west of the city, not far distant from the “upper pool” at the head of the valley of Hinnom. Here the fullers pursued their occupation.",
