        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>SHAREZER</strong> (God) protect the king!, a son of Sennacherib, king of Assyria. He and his brother Adrammelech murdered their father, and then fled into the land of Armenia (2 Kings 19:37).",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
