        "dict-easton",
        "Dictionary",
        "Easton.",
        "<strong>Dictionary (Easton's).</strong> <strong>DISH</strong> for eating from (2 Kings 21:13). Judas dipped his hand with a “sop” or piece of bread in the same dish with our Lord, thereby indicating friendly intimacy (Matthew 26:23). The “lordly dish” in Judges 5:25 was probably the shallow drinking cup, usually of brass. In Judges 6:38 the same Hebrew word is rendered “bowl.” The dishes of the tabernacle were made of pure gold (Exodus 25:29; 37:16).",
        "Easton's Illustrated Bible Dictionary, M. G. Easton (1897). Public domain.",
