    (
        22,
        8,
        "",
        "I have found the book of the law",
        "comm-contextual",
        "Note",
        "Note",
        '<strong>The book of the law found.</strong> 622 BCE. During temple repairs under Josiah, Hilkiah the high priest finds a "book of the law" (<em>sefer ha-torah</em>) — read by mainstream scholarship as some form of Deuteronomy (W. M. L. de Wette, 1805 — the foundational hypothesis of Pentateuchal source criticism). The book’s discovery triggers Josiah’s comprehensive reform (chapter 23) — destruction of the high places, centralization of worship in Jerusalem, the Passover celebration. Whether the book was newly composed, freshly redacted, or genuinely rediscovered is one of the central debates of OT scholarship. The reform itself is independently visible in the archaeological record — countryside cult sites going out of use in the late 7th century.',
        "User original",
    ),
