    (
        23,
        10,
        "",
        "Topheth in the valley of the children of Hinnom",
        "comm",
        "Note",
        "Note",
        """<strong>Topheth and Gehenna.</strong> Josiah defiles the Tophet — the Hinnom valley site where children had been burned as sacrifices to Molech (cf. Jer 7:31). The valley’s Hebrew name, <em>Ge-Hinnom</em>, becomes the Greek <em>Gehenna</em>, used throughout the New Testament for the place of final judgment (Mt 5:22, 5:29–30, 10:28, etc.). The geographic fact — that the NT’s preeminent image for hell is a specific Jerusalem valley with a specific atrocious history — is itself theologically loaded. The eschatological term retains the memory of the historical horror.""",
        "User original",
    ),
