    (
        24,
        14,
        "",
        "carried away all Jerusalem",
        "comm",
        "Note",
        "Note",
        """<strong>The first deportation.</strong> 597 BCE. Nebuchadnezzar’s first siege ends in surrender; Jehoiachin and the Jerusalem elite are taken to Babylon. Among them: Ezekiel, who prophesies from Babylon by the Chebar canal (Ezek 1:1). The "good figs" of Jer 24 are the deportees of 597, the "bad figs" are those left in Jerusalem who must endure the more catastrophic 586 destruction. The Babylonian ration tablets discovered in the South Citadel of Babylon (published by Weidner, 1939) record provisions for "Yaukin king of Yahud" — Jehoiachin himself — confirming the biblical narrative of his Babylonian residence in striking detail.""",
        "User original",
    ),
